const UXRESP_VERSION='2026.08.15-resp1';
function uxrespText(el){return (el?.textContent||'').replace(/\s+/g,' ').trim().toLowerCase()}
function uxrespTag(host,text,tone='info'){if(!host||host.querySelector('.uxresp-tag'))return;const tag=document.createElement('span');tag.className=`uxresp-tag ${tone}`;tag.textContent=text;host.appendChild(tag)}
function uxrespDecorate(){const main=document.querySelector('.main');if(!main)return;main.querySelectorAll('.metric').forEach(m=>{const label=uxrespText(m.querySelector('.metric-label'));if(label.includes('ждут проверки'))uxrespTag(m,'Действие администратора','admin');else if(label.includes('на исправлении'))uxrespTag(m,'Ожидаем водителя','driver')});main.querySelectorAll('.wl-item').forEach(item=>{const status=uxrespText(item.querySelector('.badge'));const body=item.querySelector('.wl-card-body')||item.querySelector('.wl-card-main')||item;if(status.includes('исправ'))uxrespTag(body,'Действие: водитель','driver');else if(status.includes('провер'))uxrespTag(body,'Действие: администратор','admin')});const title=uxrespText(main.querySelector('.page-title'));if(title.includes('исправ')&&document.body.dataset.role==='driver'){const head=main.querySelector('.page-head');if(head&&!main.querySelector('.uxresp-banner')){const b=document.createElement('div');b.className='uxresp-banner';b.innerHTML='<strong>Нужно ваше действие</strong><span>Проверьте замечание и отправьте исправленные данные.</span>';head.insertAdjacentElement('afterend',b)}}}
let uxrespPending=false;function uxrespSchedule(){if(uxrespPending)return;uxrespPending=true;queueMicrotask(()=>{uxrespPending=false;uxrespDecorate()})}new MutationObserver(uxrespSchedule).observe(document.documentElement,{childList:true,subtree:true});uxrespSchedule();